/**
 * Icons — átomo genérico del design system "DBoard V1.1.X" (Figma node
 * 7458:36381, "Icons"), 1:1 con las variantes reales del componente: mismos
 * 16 nombres, mismo par Outline/Fill por ícono (menos `play-circle`, que en
 * Figma solo tiene Outline). Paths exportados directo del archivo vía
 * `node.exportAsync({format:'SVG_STRING'})`, no redibujados a mano — evita
 * la divergencia que ya existía en RailIcon/Sidebar2Icon (glifos "parecidos"
 * pero con geometría propia, o directamente de otro node de Figma).
 *
 * No reemplaza a RailIcon/Sidebar2Icon/RailSemanticIcon todavía — conviven
 * hasta que se decida migrar cada consumidor.
 */
export function Icons({ icon, style = 'Outline', size = 18, className = '' }: IconsProps): React.ReactElement {
  const variants = PATHS[icon];
  const d = variants[style] ?? variants.Outline;
  return (
    <svg
      className={`block shrink-0 ${className}`}
      style={{ width: size, height: size }}
      viewBox="0 0 18 18"
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d={d} />
    </svg>
  );
}
